#!/usr/bin/env python3
"""TwinGuard - Pi control service.

A small HTTPS service the phone app drives. It owns the scan loop, so the
app's buttons (monitoring on/off, interval, Scan Now) and the app's settings
(scan listed as passive/listen-only) actually control the Pi, and it reports
real telemetry read from the hardware.

Security:
  * HTTPS only, with a self-signed certificate generated by the installer.
    The app pins that certificate's SHA-256 fingerprint (printed by the
    installer), so a man in the middle cannot impersonate the Pi.
  * Every request must carry the API key in the X-TwinGuard-Key header. The
    key is generated by the installer and read from a chmod-600 file.
  * The service only ever listens on the air. There is no transmit path:
    "active" scanning is not offered, by design.

Endpoints (all under /api/v1, all require the key except /health):
  GET  /health                 liveness, no key, no secrets
  GET  /status                 telemetry + monitoring state + upload stats
  POST /scan                   run one sweep now  -> {scanned, threats}
  POST /monitoring {enabled}   start/stop the continuous loop
  POST /config {interval}      set sweep interval (seconds)
  POST /time {epoch_ms}        phone pushes its clock to the RTC-less Pi
  GET  /trusted                list trusted BSSIDs
  PUT  /trusted {entries:[]}   replace the trusted list
  GET  /events                 Server-Sent Events: scan + alert stream
"""
import functools
import json
import os
import queue
import ssl
import sys
import threading
import time

from flask import Flask, Response, jsonify, request

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import tg_system          # noqa: E402
import tg_engine          # noqa: E402
from tg_trusted import TrustedList        # noqa: E402
from tg_firestore import FirestoreUploader, AuthError  # noqa: E402
from scanner import scan_networks          # noqa: E402

CONFIG_PATH = os.environ.get(
    "TWINGUARD_CONFIG",
    os.path.expanduser("~/.config/twinguard/service.json"))


def log(msg):
    print(f"[CONTROL] {msg}", flush=True)


def load_config():
    with open(CONFIG_PATH) as f:
        return json.load(f)


class Service:
    def __init__(self, cfg):
        self.cfg = cfg
        self.iface = cfg.get("interface", "wlan1")
        self.data_dir = cfg.get("data_dir",
                                os.path.expanduser("~/.local/share/twinguard"))
        os.makedirs(self.data_dir, exist_ok=True)

        self.clock = tg_system.Clock()
        self.trusted = TrustedList(os.path.join(self.data_dir, "trusted.json"))

        fb = cfg["firebase"]
        self.uploader = FirestoreUploader(fb, self.data_dir)

        self.scan_duration = int(cfg.get("scan_duration", 8))
        self.interval = int(cfg.get("interval", 60))
        self.monitoring = bool(cfg.get("monitoring", True))

        self.engine = None
        self.lock = threading.Lock()
        self.scanning = False
        self.last_scan_at = None
        self.last_scan_result = None
        self.total_scans = 0
        self.total_networks = 0
        self._wake = threading.Event()
        self._subscribers = []
        self._sub_lock = threading.Lock()

    # -- startup ---------------------------------------------------------------
    def start(self):
        try:
            uid, username = self.uploader.start()
        except AuthError as e:
            log(f"FATAL: operator sign-in refused ({e}). Check the credentials "
                f"in {CONFIG_PATH}. The service will stay up so /status is "
                f"reachable, but nothing will upload.")
            uid, username = self.cfg["firebase"].get("uid"), \
                self.cfg["firebase"].get("username")
        self.engine = tg_engine.Engine(uid, username, self.trusted, self.clock)
        threading.Thread(target=self._loop, name="scan-loop", daemon=True).start()
        log(f"interface={self.iface} interval={self.interval}s "
            f"monitoring={self.monitoring}")

    # -- scanning --------------------------------------------------------------
    def run_scan(self):
        """One sweep: airodump -> parse -> score -> seal -> queue uploads."""
        with self.lock:
            if self.scanning:
                return {"ok": False, "error": "a scan is already running"}
            self.scanning = True
        try:
            networks = scan_networks(interface=self.iface,
                                     duration=self.scan_duration)
            alerts, verdicts = self.engine.analyze(networks)
            scan_record = self.engine.build_scan_record(networks, verdicts)

            self.uploader.enqueue("scan", scan_record["sha256_hash"], scan_record)
            for a in alerts:
                self.uploader.enqueue("detection", a["sha256_hash"], a)
                self._publish("alert", a)

            self.total_scans += 1
            self.total_networks += len(networks)
            self.last_scan_at = time.time()
            self.last_scan_result = {
                "scanned": len(networks),
                "threats": len(alerts),
                "at": self.last_scan_at,
            }
            self._publish("scan", {
                "scanned": len(networks),
                "threats": len(alerts),
                "at": self.last_scan_at,
                "networks": scan_record["networks"],
            })
            log(f"scan #{self.total_scans}: {len(networks)} networks, "
                f"{len(alerts)} alert(s)")
            return {"ok": True, **self.last_scan_result}
        finally:
            with self.lock:
                self.scanning = False

    def _loop(self):
        while True:
            if self.monitoring:
                try:
                    self.run_scan()
                except Exception as e:  # a bad scan must not kill the loop
                    log(f"scan error: {e}")
                self._wake.wait(self.interval)
            else:
                self._wake.wait(5)
            self._wake.clear()

    def set_monitoring(self, enabled):
        self.monitoring = bool(enabled)
        self._wake.set()

    def set_interval(self, seconds):
        self.interval = max(15, min(3600, int(seconds)))
        self._wake.set()
        return self.interval

    # -- events (SSE) ----------------------------------------------------------
    def _publish(self, kind, data):
        msg = f"event: {kind}\ndata: {json.dumps(data)}\n\n"
        with self._sub_lock:
            dead = []
            for q in self._subscribers:
                try:
                    q.put_nowait(msg)
                except queue.Full:
                    dead.append(q)
            for q in dead:
                self._subscribers.remove(q)

    def subscribe(self):
        q = queue.Queue(maxsize=50)
        with self._sub_lock:
            self._subscribers.append(q)
        return q

    def unsubscribe(self, q):
        with self._sub_lock:
            if q in self._subscribers:
                self._subscribers.remove(q)

    # -- status ----------------------------------------------------------------
    def status(self):
        tel = tg_system.telemetry(self.iface)
        return {
            "ok": True,
            "service": "twinguard",
            "version": tg_system.VERSION,
            "monitoring": self.monitoring,
            "scanning": self.scanning,
            "scan_mode": "passive",
            "interval": self.interval,
            "interface": self.iface,
            "last_scan": self.last_scan_result,
            "total_scans": self.total_scans,
            "total_networks": self.total_networks,
            "telemetry": tel,
            "clock": self.clock.status(),
            "upload": self.uploader.status(),
            "trusted_count": len(self.trusted.bssids()),
        }


# ── HTTP layer ────────────────────────────────────────────────────────────────
def build_app(service, api_key):
    app = Flask(__name__)

    def require_key(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            supplied = request.headers.get("X-TwinGuard-Key", "")
            # length-constant-ish comparison
            if not supplied or not _safe_eq(supplied, api_key):
                return jsonify({"ok": False, "error": "unauthorized"}), 401
            return fn(*a, **kw)
        return wrapper

    @app.get("/api/v1/health")
    def health():
        return jsonify({"ok": True, "service": "twinguard",
                        "version": tg_system.VERSION})

    @app.get("/api/v1/status")
    @require_key
    def status():
        return jsonify(service.status())

    @app.post("/api/v1/scan")
    @require_key
    def scan():
        return jsonify(service.run_scan())

    @app.post("/api/v1/monitoring")
    @require_key
    def monitoring():
        data = request.get_json(force=True, silent=True) or {}
        if "enabled" not in data:
            return jsonify({"ok": False, "error": "enabled required"}), 400
        service.set_monitoring(bool(data["enabled"]))
        return jsonify({"ok": True, "monitoring": service.monitoring})

    @app.post("/api/v1/config")
    @require_key
    def config():
        data = request.get_json(force=True, silent=True) or {}
        out = {"ok": True}
        if "interval" in data:
            out["interval"] = service.set_interval(data["interval"])
        return jsonify(out)

    @app.post("/api/v1/time")
    @require_key
    def set_time():
        data = request.get_json(force=True, silent=True) or {}
        epoch_ms = data.get("epoch_ms")
        if not isinstance(epoch_ms, (int, float)):
            return jsonify({"ok": False, "error": "epoch_ms required"}), 400
        result = service.clock.set_from_phone(epoch_ms)
        return jsonify({"ok": True, **result})

    @app.get("/api/v1/trusted")
    @require_key
    def get_trusted():
        return jsonify({"ok": True, "entries": service.trusted.as_list()})

    @app.put("/api/v1/trusted")
    @require_key
    def put_trusted():
        data = request.get_json(force=True, silent=True) or {}
        entries = data.get("entries", [])
        if not isinstance(entries, list):
            return jsonify({"ok": False, "error": "entries must be a list"}), 400
        stored = service.trusted.replace(entries)
        service._wake.set()
        return jsonify({"ok": True, "entries": stored})

    @app.get("/api/v1/events")
    @require_key
    def events():
        q = service.subscribe()

        def stream():
            try:
                yield "event: hello\ndata: {}\n\n"
                while True:
                    try:
                        yield q.get(timeout=20)
                    except queue.Empty:
                        yield ": keepalive\n\n"
            finally:
                service.unsubscribe(q)

        return Response(stream(), mimetype="text/event-stream",
                        headers={"Cache-Control": "no-cache",
                                 "X-Accel-Buffering": "no"})

    return app


def _safe_eq(a, b):
    if len(a) != len(b):
        return False
    r = 0
    for x, y in zip(a, b):
        r |= ord(x) ^ ord(y)
    return r == 0


def main():
    cfg = load_config()
    key_path = os.path.expanduser(cfg["api_key_file"])
    with open(key_path) as f:
        api_key = f.read().strip()

    service = Service(cfg)
    service.start()
    app = build_app(service, api_key)

    cert = os.path.expanduser(cfg["tls_cert"])
    key = os.path.expanduser(cfg["tls_key"])
    ctx = ssl.SSLContext(ssl.PROTOCOL_TLS_SERVER)
    ctx.load_cert_chain(cert, key)

    host = cfg.get("bind", "0.0.0.0")
    port = int(cfg.get("port", 8080))
    log(f"HTTPS control service on {host}:{port} (cert {cert})")
    app.run(host=host, port=port, ssl_context=ctx, threaded=True)


if __name__ == "__main__":
    main()
